window.FAIO_SOURCES = {"q01": "\"\"\"Общие помощники для проверки ответов.\"\"\"\nimport re\n\nNUM_RE = re.compile(r\"[-+]?\\d*\\.?\\d+(?:[eE][-+]?\\d+)?\")\n\n\ndef floats(text):\n    \"\"\"Все числа из текста в виде списка float.\"\"\"\n    return [float(x) for x in NUM_RE.findall(text or \"\")]\n\n\ndef close(a, b, rel=1e-6, abs_=1e-9):\n    return abs(a - b) <= max(abs_, rel * max(abs(a), abs(b)))\n\n\ndef one_number(out):\n    \"\"\"Ровно одно число в выводе. Возвращает (ok, value, msg).\"\"\"\n    got = floats(out)\n    if len(got) != 1:\n        return False, None, f\"ожидалось одно число, найдено {len(got)}\"\n    return True, got[0], \"\"\n\n\ndef cmp_numbers(out, expected, rel=1e-6, abs_=1e-9, names=None):\n    \"\"\"Сравнить последовательность чисел из вывода с эталоном.\"\"\"\n    got = floats(out)\n    if len(got) != len(expected):\n        return False, f\"ожидалось {len(expected)} чисел, получено {len(got)}\"\n    for i, (g, e) in enumerate(zip(got, expected)):\n        if not close(g, e, rel, abs_):\n            name = names[i] if names and i < len(names) else f\"число #{i + 1}\"\n            return False, f\"{name}: ожидалось {e:.6g}, получено {g:.6g}\"\n    return True, \"\"\n\n\ndef cmp_multiset(out, expected, tol=1e-6):\n    \"\"\"Сравнить набор чисел без учёта порядка.\"\"\"\n    got = sorted(floats(out))\n    exp = sorted(expected)\n    if len(got) != len(exp):\n        return False, f\"ожидалось {len(exp)} значений, получено {len(got)}\"\n    for g, e in zip(got, exp):\n        if not close(g, e, 1e-6, tol):\n            return False, f\"значение {g:.6g} не совпало с ожидаемым {e:.6g}\"\n    return True, \"\"\n\n\n\"\"\"q01 — среднее, мода, медиана.\"\"\"\nimport re\n\n\nID = \"q01\"\nTITLE = \"Статистика 101\"\nTOPIC = \"математика и статистика\"\nLEVEL = 1\nPOINTS = 10\nSOURCE = \"FAIO-2025, отбор, задача 1\"\n\nSTATEMENT = \"\"\"\nВ классе несколько учеников, каждый сказал, сколько у него домашних животных.\n\nНайдите три величины этого набора чисел:\n  1) среднее арифметическое,\n  2) моду (значение, которое встречается чаще всех; она единственна),\n  3) медиану (серединное значение упорядоченного набора; при чётном\n     количестве элементов — среднее двух серединных).\n\nВХОД\n  Одна строка: числа через пробел.\n\nВЫХОД\n  Три числа в одной строке через пробел: среднее, мода, медиана.\n  Не менее четырёх знаков после запятой у дробных значений.\n\nПРИМЕР\n  вход:   2 0 1 3 2 1 0 4 1 1\n  выход:  1.5 1 1\n\"\"\"\n\nTEMPLATE = '''import sys\n\ndata = [int(x) for x in sys.stdin.read().split()]\n\n# среднее\nmean = sum(data) / len(data)\n\n# мода: подсчитайте, сколько раз встречается каждое значение\n# медиана: отсортируйте список\n\nprint(mean, mode, median)\n'''\n\n\ndef gen(rng):\n    n = rng.randint(9, 16)\n    mode_val = rng.randint(0, 5)\n    data = [mode_val] * rng.randint(4, 6)\n    others = [v for v in range(0, 6) if v != mode_val]\n    while len(data) < n:\n        data.append(rng.choice(others))\n    # у моды должно быть строгое преимущество\n    counts = {v: data.count(v) for v in set(data)}\n    while sorted(counts.values())[-1] == sorted(counts.values())[-2]:\n        data.append(mode_val)\n        counts = {v: data.count(v) for v in set(data)}\n    rng.shuffle(data)\n    return \" \".join(map(str, data)) + \"\\n\", {}\n\n\ndef _answer(data):\n    mean = sum(data) / len(data)\n    counts = {v: data.count(v) for v in set(data)}\n    mode = max(counts, key=lambda v: (counts[v], -v))\n    s = sorted(data)\n    mid = len(s) // 2\n    median = s[mid] if len(s) % 2 else (s[mid - 1] + s[mid]) / 2\n    return mean, mode, median\n\n\ndef solve(inp):\n    data = [int(x) for x in inp.split()]\n    mean, mode, median = _answer(data)\n    return f\"{mean:.6f} {mode} {median:.6f}\\n\"\n\n\ndef check(inp, out, payload):\n    data = [int(x) for x in inp.split()]\n    return cmp_numbers(out, list(_answer(data)), rel=1e-4, abs_=1e-4,\n                       names=[\"среднее\", \"мода\", \"медиана\"])\n", "q02": "\"\"\"Общие помощники для проверки ответов.\"\"\"\nimport re\n\nNUM_RE = re.compile(r\"[-+]?\\d*\\.?\\d+(?:[eE][-+]?\\d+)?\")\n\n\ndef floats(text):\n    \"\"\"Все числа из текста в виде списка float.\"\"\"\n    return [float(x) for x in NUM_RE.findall(text or \"\")]\n\n\ndef close(a, b, rel=1e-6, abs_=1e-9):\n    return abs(a - b) <= max(abs_, rel * max(abs(a), abs(b)))\n\n\ndef one_number(out):\n    \"\"\"Ровно одно число в выводе. Возвращает (ok, value, msg).\"\"\"\n    got = floats(out)\n    if len(got) != 1:\n        return False, None, f\"ожидалось одно число, найдено {len(got)}\"\n    return True, got[0], \"\"\n\n\ndef cmp_numbers(out, expected, rel=1e-6, abs_=1e-9, names=None):\n    \"\"\"Сравнить последовательность чисел из вывода с эталоном.\"\"\"\n    got = floats(out)\n    if len(got) != len(expected):\n        return False, f\"ожидалось {len(expected)} чисел, получено {len(got)}\"\n    for i, (g, e) in enumerate(zip(got, expected)):\n        if not close(g, e, rel, abs_):\n            name = names[i] if names and i < len(names) else f\"число #{i + 1}\"\n            return False, f\"{name}: ожидалось {e:.6g}, получено {g:.6g}\"\n    return True, \"\"\n\n\ndef cmp_multiset(out, expected, tol=1e-6):\n    \"\"\"Сравнить набор чисел без учёта порядка.\"\"\"\n    got = sorted(floats(out))\n    exp = sorted(expected)\n    if len(got) != len(exp):\n        return False, f\"ожидалось {len(exp)} значений, получено {len(got)}\"\n    for g, e in zip(got, exp):\n        if not close(g, e, 1e-6, tol):\n            return False, f\"значение {g:.6g} не совпало с ожидаемым {e:.6g}\"\n    return True, \"\"\n\n\n\"\"\"q02 — вероятность «хотя бы один раз».\"\"\"\n\n\nID = \"q02\"\nTITLE = \"Хотя бы одна шестёрка\"\nTOPIC = \"математика и статистика\"\nLEVEL = 1\nPOINTS = 10\nSOURCE = \"FAIO-2025, отбор, задача 2\"\n\nSTATEMENT = \"\"\"\nИгральный кубик имеет d граней с числами от 1 до d. Его бросают k раз подряд.\n\nНайдите вероятность того, что хотя бы один раз выпадет грань с числом d.\n\nПодсказка: считать «хотя бы один» напрямую долго — проще найти вероятность\nпротивоположного события (не выпало ни разу) и вычесть её из единицы.\n\nВХОД\n  Одна строка: два целых числа d и k (2 <= d <= 20, 1 <= k <= 50).\n\nВЫХОД\n  Вероятность — десятичная дробь с четырьмя знаками после запятой.\n\nПРИМЕР\n  вход:   6 3\n  выход:  0.4213\n\"\"\"\n\nTEMPLATE = '''import sys\n\nd, k = [int(x) for x in sys.stdin.read().split()]\n\np = ...  # вероятность того, что грань d выпадет хотя бы раз\n\nprint(f\"{p:.4f}\")\n'''\n\n\ndef gen(rng):\n    d = rng.choice([4, 6, 6, 8, 10, 12, 20])\n    k = rng.randint(1, 20)\n    return f\"{d} {k}\\n\", {}\n\n\ndef solve(inp):\n    d, k = [int(x) for x in inp.split()]\n    return f\"{1 - ((d - 1) / d) ** k:.4f}\\n\"\n\n\ndef check(inp, out, payload):\n    d, k = [int(x) for x in inp.split()]\n    return cmp_numbers(out, [1 - ((d - 1) / d) ** k], rel=1e-4, abs_=1e-4,\n                       names=[\"вероятность\"])\n", "q03": "\"\"\"Общие помощники для проверки ответов.\"\"\"\nimport re\n\nNUM_RE = re.compile(r\"[-+]?\\d*\\.?\\d+(?:[eE][-+]?\\d+)?\")\n\n\ndef floats(text):\n    \"\"\"Все числа из текста в виде списка float.\"\"\"\n    return [float(x) for x in NUM_RE.findall(text or \"\")]\n\n\ndef close(a, b, rel=1e-6, abs_=1e-9):\n    return abs(a - b) <= max(abs_, rel * max(abs(a), abs(b)))\n\n\ndef one_number(out):\n    \"\"\"Ровно одно число в выводе. Возвращает (ok, value, msg).\"\"\"\n    got = floats(out)\n    if len(got) != 1:\n        return False, None, f\"ожидалось одно число, найдено {len(got)}\"\n    return True, got[0], \"\"\n\n\ndef cmp_numbers(out, expected, rel=1e-6, abs_=1e-9, names=None):\n    \"\"\"Сравнить последовательность чисел из вывода с эталоном.\"\"\"\n    got = floats(out)\n    if len(got) != len(expected):\n        return False, f\"ожидалось {len(expected)} чисел, получено {len(got)}\"\n    for i, (g, e) in enumerate(zip(got, expected)):\n        if not close(g, e, rel, abs_):\n            name = names[i] if names and i < len(names) else f\"число #{i + 1}\"\n            return False, f\"{name}: ожидалось {e:.6g}, получено {g:.6g}\"\n    return True, \"\"\n\n\ndef cmp_multiset(out, expected, tol=1e-6):\n    \"\"\"Сравнить набор чисел без учёта порядка.\"\"\"\n    got = sorted(floats(out))\n    exp = sorted(expected)\n    if len(got) != len(exp):\n        return False, f\"ожидалось {len(exp)} значений, получено {len(got)}\"\n    for g, e in zip(got, exp):\n        if not close(g, e, 1e-6, tol):\n            return False, f\"значение {g:.6g} не совпало с ожидаемым {e:.6g}\"\n    return True, \"\"\n\n\n\"\"\"q03 — формула Байеса.\"\"\"\n\n\nID = \"q03\"\nTITLE = \"Тест на редкую болезнь\"\nTOPIC = \"математика и статистика\"\nLEVEL = 1\nPOINTS = 10\nSOURCE = \"FAIO-2025, отбор, задача 3\"\n\nSTATEMENT = \"\"\"\nРедкой болезнью болеет p процентов населения. Для диагностики есть тест:\n  - если человек болен, тест даёт положительный результат в s процентах случаев\n    (чувствительность);\n  - если человек здоров, тест даёт отрицательный результат в t процентах случаев\n    (специфичность).\n\nСлучайный человек сдал тест, и результат оказался ПОЛОЖИТЕЛЬНЫМ.\nКакова вероятность, что он действительно болен?\n\nПодсказка: P(болен | +) = P(+ | болен) * P(болен) / P(+), где знаменатель\nскладывается из двух потоков — больные с верным плюсом и здоровые с ложным.\n\nВХОД\n  Одна строка: три числа p, s, t (в процентах).\n\nВЫХОД\n  Вероятность — десятичная дробь с четырьмя знаками после запятой.\n\nПРИМЕР\n  вход:   1 99 98\n  выход:  0.3333\n\"\"\"\n\nTEMPLATE = '''import sys\n\np, s, t = [float(x) for x in sys.stdin.read().split()]\np, s, t = p / 100, s / 100, t / 100\n\nanswer = ...\n\nprint(f\"{answer:.4f}\")\n'''\n\n\ndef gen(rng):\n    p = rng.choice([0.5, 1, 2, 3, 5, 10])\n    s = rng.choice([90, 95, 97, 98, 99])\n    t = rng.choice([90, 95, 96, 98, 99])\n    return f\"{p} {s} {t}\\n\", {}\n\n\ndef _answer(p, s, t):\n    p, s, t = p / 100, s / 100, t / 100\n    return p * s / (p * s + (1 - p) * (1 - t))\n\n\ndef solve(inp):\n    p, s, t = [float(x) for x in inp.split()]\n    return f\"{_answer(p, s, t):.4f}\\n\"\n\n\ndef check(inp, out, payload):\n    p, s, t = [float(x) for x in inp.split()]\n    return cmp_numbers(out, [_answer(p, s, t)], rel=1e-4, abs_=1e-4, names=[\"вероятность\"])\n", "q04": "\"\"\"Общие помощники для проверки ответов.\"\"\"\nimport re\n\nNUM_RE = re.compile(r\"[-+]?\\d*\\.?\\d+(?:[eE][-+]?\\d+)?\")\n\n\ndef floats(text):\n    \"\"\"Все числа из текста в виде списка float.\"\"\"\n    return [float(x) for x in NUM_RE.findall(text or \"\")]\n\n\ndef close(a, b, rel=1e-6, abs_=1e-9):\n    return abs(a - b) <= max(abs_, rel * max(abs(a), abs(b)))\n\n\ndef one_number(out):\n    \"\"\"Ровно одно число в выводе. Возвращает (ok, value, msg).\"\"\"\n    got = floats(out)\n    if len(got) != 1:\n        return False, None, f\"ожидалось одно число, найдено {len(got)}\"\n    return True, got[0], \"\"\n\n\ndef cmp_numbers(out, expected, rel=1e-6, abs_=1e-9, names=None):\n    \"\"\"Сравнить последовательность чисел из вывода с эталоном.\"\"\"\n    got = floats(out)\n    if len(got) != len(expected):\n        return False, f\"ожидалось {len(expected)} чисел, получено {len(got)}\"\n    for i, (g, e) in enumerate(zip(got, expected)):\n        if not close(g, e, rel, abs_):\n            name = names[i] if names and i < len(names) else f\"число #{i + 1}\"\n            return False, f\"{name}: ожидалось {e:.6g}, получено {g:.6g}\"\n    return True, \"\"\n\n\ndef cmp_multiset(out, expected, tol=1e-6):\n    \"\"\"Сравнить набор чисел без учёта порядка.\"\"\"\n    got = sorted(floats(out))\n    exp = sorted(expected)\n    if len(got) != len(exp):\n        return False, f\"ожидалось {len(exp)} значений, получено {len(got)}\"\n    for g, e in zip(got, exp):\n        if not close(g, e, 1e-6, tol):\n            return False, f\"значение {g:.6g} не совпало с ожидаемым {e:.6g}\"\n    return True, \"\"\n\n\n\"\"\"q04 — сочетания.\"\"\"\nimport re\nfrom math import comb\n\nID = \"q04\"\nTITLE = \"Выбор комплектующих\"\nTOPIC = \"математика и статистика\"\nLEVEL = 1\nPOINTS = 10\nSOURCE = \"FAIO-2024, отбор, задача A\"\n\nSTATEMENT = \"\"\"\nКоманда готовится к полёту на космическую станцию. Нужно выбрать k деталей\nракеты из n имеющихся. Сколькими способами это можно сделать?\nПорядок выбора не важен.\n\nВХОД\n  Одна строка: два натуральных числа n и k (1 <= k <= n <= 60).\n\nВЫХОД\n  Одно целое число — ответ.\n\nПРИМЕР\n  вход:   5 2\n  выход:  10\n\"\"\"\n\nTEMPLATE = '''import sys\n\nn, k = [int(x) for x in sys.stdin.read().split()]\n\n# способ 1: формула n! / (k! * (n-k)!)\n# способ 2: from math import comb\n\nprint(answer)\n'''\n\n\ndef gen(rng):\n    n = rng.randint(2, 60)\n    k = rng.randint(1, n)\n    return f\"{n} {k}\\n\", {}\n\n\ndef solve(inp):\n    n, k = [int(x) for x in inp.split()]\n    return f\"{comb(n, k)}\\n\"\n\n\ndef check(inp, out, payload):\n    n, k = [int(x) for x in inp.split()]\n    found = re.findall(r\"[-+]?\\d+\", out or \"\")\n    if len(found) != 1:\n        return False, f\"ожидалось одно целое число, найдено {len(found)}\"\n    if int(found[0]) != comb(n, k):\n        return False, f\"ожидалось {comb(n, k)}, получено {found[0]}\"\n    return True, \"\"\n", "q05": "\"\"\"Общие помощники для проверки ответов.\"\"\"\nimport re\n\nNUM_RE = re.compile(r\"[-+]?\\d*\\.?\\d+(?:[eE][-+]?\\d+)?\")\n\n\ndef floats(text):\n    \"\"\"Все числа из текста в виде списка float.\"\"\"\n    return [float(x) for x in NUM_RE.findall(text or \"\")]\n\n\ndef close(a, b, rel=1e-6, abs_=1e-9):\n    return abs(a - b) <= max(abs_, rel * max(abs(a), abs(b)))\n\n\ndef one_number(out):\n    \"\"\"Ровно одно число в выводе. Возвращает (ok, value, msg).\"\"\"\n    got = floats(out)\n    if len(got) != 1:\n        return False, None, f\"ожидалось одно число, найдено {len(got)}\"\n    return True, got[0], \"\"\n\n\ndef cmp_numbers(out, expected, rel=1e-6, abs_=1e-9, names=None):\n    \"\"\"Сравнить последовательность чисел из вывода с эталоном.\"\"\"\n    got = floats(out)\n    if len(got) != len(expected):\n        return False, f\"ожидалось {len(expected)} чисел, получено {len(got)}\"\n    for i, (g, e) in enumerate(zip(got, expected)):\n        if not close(g, e, rel, abs_):\n            name = names[i] if names and i < len(names) else f\"число #{i + 1}\"\n            return False, f\"{name}: ожидалось {e:.6g}, получено {g:.6g}\"\n    return True, \"\"\n\n\ndef cmp_multiset(out, expected, tol=1e-6):\n    \"\"\"Сравнить набор чисел без учёта порядка.\"\"\"\n    got = sorted(floats(out))\n    exp = sorted(expected)\n    if len(got) != len(exp):\n        return False, f\"ожидалось {len(exp)} значений, получено {len(got)}\"\n    for g, e in zip(got, exp):\n        if not close(g, e, 1e-6, tol):\n            return False, f\"значение {g:.6g} не совпало с ожидаемым {e:.6g}\"\n    return True, \"\"\n\n\n\"\"\"q05 — матожидание времени до первого успеха.\"\"\"\n\n\nID = \"q05\"\nTITLE = \"Метеориты с золотом\"\nTOPIC = \"математика и статистика\"\nLEVEL = 2\nPOINTS = 20\nSOURCE = \"FAIO-2024, отбор, задача H\"\n\nSTATEMENT = \"\"\"\nВокруг станции летает x метеоритов, ровно g из них содержат золото.\nКаждую минуту гравитационная матрица притягивает ровно один метеорит,\nвсе оставшиеся метеориты равновероятны.\n\nСколько в среднем пройдёт минут до того, как притянется первый метеорит\nс золотом (считая ту минуту, когда он притянулся)?\n\nПодсказка: представьте случайную перестановку всех x метеоритов. Золотые\nделят остальные на g+1 промежутков, и по симметрии в каждом промежутке\nв среднем одинаковое число обычных метеоритов.\n\nВХОД\n  Одна строка: два натуральных числа x и g (0 < g <= x < 100000).\n\nВЫХОД\n  Одно число — матожидание, десятичная дробь.\n\nПРИМЕР\n  вход:   1 1\n  выход:  1.0\n\"\"\"\n\nTEMPLATE = '''import sys\n\nx, g = [int(v) for v in sys.stdin.read().split()]\n\nanswer = ...\n\nprint(f\"{answer:.6f}\")\n'''\n\n\ndef gen(rng):\n    x = rng.randint(1, 5000)\n    g = rng.randint(1, x)\n    return f\"{x} {g}\\n\", {}\n\n\ndef solve(inp):\n    x, g = [int(v) for v in inp.split()]\n    return f\"{(x + 1) / (g + 1):.6f}\\n\"\n\n\ndef check(inp, out, payload):\n    x, g = [int(v) for v in inp.split()]\n    return cmp_numbers(out, [(x + 1) / (g + 1)], rel=1e-4, abs_=1e-4, names=[\"матожидание\"])\n", "q06": "\"\"\"Общие помощники для проверки ответов.\"\"\"\nimport re\n\nNUM_RE = re.compile(r\"[-+]?\\d*\\.?\\d+(?:[eE][-+]?\\d+)?\")\n\n\ndef floats(text):\n    \"\"\"Все числа из текста в виде списка float.\"\"\"\n    return [float(x) for x in NUM_RE.findall(text or \"\")]\n\n\ndef close(a, b, rel=1e-6, abs_=1e-9):\n    return abs(a - b) <= max(abs_, rel * max(abs(a), abs(b)))\n\n\ndef one_number(out):\n    \"\"\"Ровно одно число в выводе. Возвращает (ok, value, msg).\"\"\"\n    got = floats(out)\n    if len(got) != 1:\n        return False, None, f\"ожидалось одно число, найдено {len(got)}\"\n    return True, got[0], \"\"\n\n\ndef cmp_numbers(out, expected, rel=1e-6, abs_=1e-9, names=None):\n    \"\"\"Сравнить последовательность чисел из вывода с эталоном.\"\"\"\n    got = floats(out)\n    if len(got) != len(expected):\n        return False, f\"ожидалось {len(expected)} чисел, получено {len(got)}\"\n    for i, (g, e) in enumerate(zip(got, expected)):\n        if not close(g, e, rel, abs_):\n            name = names[i] if names and i < len(names) else f\"число #{i + 1}\"\n            return False, f\"{name}: ожидалось {e:.6g}, получено {g:.6g}\"\n    return True, \"\"\n\n\ndef cmp_multiset(out, expected, tol=1e-6):\n    \"\"\"Сравнить набор чисел без учёта порядка.\"\"\"\n    got = sorted(floats(out))\n    exp = sorted(expected)\n    if len(got) != len(exp):\n        return False, f\"ожидалось {len(exp)} значений, получено {len(got)}\"\n    for g, e in zip(got, exp):\n        if not close(g, e, 1e-6, tol):\n            return False, f\"значение {g:.6g} не совпало с ожидаемым {e:.6g}\"\n    return True, \"\"\n\n\n\"\"\"q06 — поиск выбросов методом межквартильного размаха.\"\"\"\n\n\nID = \"q06\"\nTITLE = \"Выбросы по правилу IQR\"\nTOPIC = \"анализ данных\"\nLEVEL = 2\nPOINTS = 20\nSOURCE = \"FAIO-2024, финал, задача B\"\n\nSTATEMENT = \"\"\"\nСтажёр Дархан должен был ездить на метеостанцию и измерять чистоту льда,\nно часть значений он просто выдумал. Найдите подделки — выбросы в данных.\n\nМетод межквартильного размаха (IQR):\n  Q1 — 25-й процентиль, Q3 — 75-й процентиль, IQR = Q3 - Q1.\n  Выбросом считается значение вне отрезка [Q1 - 1.5*IQR, Q3 + 1.5*IQR].\n\nПроцентили считайте методом линейной интерполяции: для доли p возьмите\nиндекс h = p * (N - 1) в отсортированном массиве и линейно интерполируйте\nмежду соседними элементами (так работает numpy.percentile по умолчанию).\n\nВХОД\n  Одна строка: N вещественных значений через пробел.\n\nВЫХОД\n  Все значения-выбросы в одну строку через пробел. Порядок любой.\n\nПРИМЕР\n  вход:   10 11 12 11 10 12 11 500 -400 10 11 12\n  выход:  500 -400\n\"\"\"\n\nTEMPLATE = '''import sys\n\ndata = [float(x) for x in sys.stdin.read().split()]\ns = sorted(data)\n\n\ndef percentile(sorted_values, p):\n    h = p * (len(sorted_values) - 1)\n    lo = int(h)\n    hi = min(lo + 1, len(sorted_values) - 1)\n    return sorted_values[lo] + (h - lo) * (sorted_values[hi] - sorted_values[lo])\n\n\nq1 = percentile(s, 0.25)\nq3 = percentile(s, 0.75)\niqr = q3 - q1\n\noutliers = [x for x in data if ...]\n\nprint(\" \".join(str(x) for x in outliers))\n'''\n\n\ndef _percentile(s, p):\n    h = p * (len(s) - 1)\n    lo = int(h)\n    hi = min(lo + 1, len(s) - 1)\n    return s[lo] + (h - lo) * (s[hi] - s[lo])\n\n\ndef _outliers(data):\n    s = sorted(data)\n    q1, q3 = _percentile(s, 0.25), _percentile(s, 0.75)\n    iqr = q3 - q1\n    lo, hi = q1 - 1.5 * iqr, q3 + 1.5 * iqr\n    return [x for x in data if x < lo or x > hi]\n\n\ndef gen(rng):\n    n = rng.randint(200, 400)\n    data = [round(rng.uniform(400, 1000), 3) for _ in range(n)]\n    for _ in range(rng.randint(4, 14)):\n        if rng.random() < 0.5:\n            data.append(round(rng.uniform(-200, 50), 3))\n        else:\n            data.append(round(rng.uniform(1450, 1900), 3))\n    rng.shuffle(data)\n    return \" \".join(map(str, data)) + \"\\n\", {}\n\n\ndef solve(inp):\n    return \" \".join(str(x) for x in _outliers(floats(inp))) + \"\\n\"\n\n\ndef check(inp, out, payload):\n    return cmp_multiset(out, _outliers(floats(inp)), tol=1e-6)\n", "q07": "\"\"\"Общие помощники для проверки ответов.\"\"\"\nimport re\n\nNUM_RE = re.compile(r\"[-+]?\\d*\\.?\\d+(?:[eE][-+]?\\d+)?\")\n\n\ndef floats(text):\n    \"\"\"Все числа из текста в виде списка float.\"\"\"\n    return [float(x) for x in NUM_RE.findall(text or \"\")]\n\n\ndef close(a, b, rel=1e-6, abs_=1e-9):\n    return abs(a - b) <= max(abs_, rel * max(abs(a), abs(b)))\n\n\ndef one_number(out):\n    \"\"\"Ровно одно число в выводе. Возвращает (ok, value, msg).\"\"\"\n    got = floats(out)\n    if len(got) != 1:\n        return False, None, f\"ожидалось одно число, найдено {len(got)}\"\n    return True, got[0], \"\"\n\n\ndef cmp_numbers(out, expected, rel=1e-6, abs_=1e-9, names=None):\n    \"\"\"Сравнить последовательность чисел из вывода с эталоном.\"\"\"\n    got = floats(out)\n    if len(got) != len(expected):\n        return False, f\"ожидалось {len(expected)} чисел, получено {len(got)}\"\n    for i, (g, e) in enumerate(zip(got, expected)):\n        if not close(g, e, rel, abs_):\n            name = names[i] if names and i < len(names) else f\"число #{i + 1}\"\n            return False, f\"{name}: ожидалось {e:.6g}, получено {g:.6g}\"\n    return True, \"\"\n\n\ndef cmp_multiset(out, expected, tol=1e-6):\n    \"\"\"Сравнить набор чисел без учёта порядка.\"\"\"\n    got = sorted(floats(out))\n    exp = sorted(expected)\n    if len(got) != len(exp):\n        return False, f\"ожидалось {len(exp)} значений, получено {len(got)}\"\n    for g, e in zip(got, exp):\n        if not close(g, e, 1e-6, tol):\n            return False, f\"значение {g:.6g} не совпало с ожидаемым {e:.6g}\"\n    return True, \"\"\n\n\n\"\"\"q07 — поиск выбросов по z-оценке.\"\"\"\n\n\nID = \"q07\"\nTITLE = \"Выбросы по z-оценке\"\nTOPIC = \"анализ данных\"\nLEVEL = 2\nPOINTS = 20\nSOURCE = \"FAIO-2024, финал, задача B (второй метод)\"\n\nSTATEMENT = \"\"\"\nТот же набор измерений, но другой метод поиска выбросов — z-оценка.\n\nДля каждого значения x считается z = (x - mean) / sigma, где mean — среднее\nвсего набора, sigma — стандартное отклонение всего набора (делите сумму\nквадратов отклонений на N, без поправки Бесселя).\n\nВыбросом считается значение с |z| > 3.\n\nВХОД\n  Одна строка: N вещественных значений через пробел.\n\nВЫХОД\n  Все значения-выбросы в одну строку через пробел. Порядок любой.\n\"\"\"\n\nTEMPLATE = '''import sys\nfrom math import sqrt\n\ndata = [float(x) for x in sys.stdin.read().split()]\n\nmean = sum(data) / len(data)\nsigma = sqrt(sum((x - mean) ** 2 for x in data) / len(data))\n\noutliers = [x for x in data if ...]\n\nprint(\" \".join(str(x) for x in outliers))\n'''\n\n\ndef _outliers(data):\n    mean = sum(data) / len(data)\n    sigma = (sum((x - mean) ** 2 for x in data) / len(data)) ** 0.5\n    return [x for x in data if abs(x - mean) > 3 * sigma]\n\n\ndef gen(rng):\n    n = rng.randint(300, 500)\n    center = rng.uniform(200, 800)\n    spread = rng.uniform(50, 120)\n    data = [round(center + rng.uniform(-spread, spread), 3) for _ in range(n)]\n    for _ in range(rng.randint(3, 8)):\n        sign = 1 if rng.random() < 0.5 else -1\n        data.append(round(center + sign * spread * rng.uniform(12, 20), 3))\n    rng.shuffle(data)\n    return \" \".join(map(str, data)) + \"\\n\", {}\n\n\ndef solve(inp):\n    return \" \".join(str(x) for x in _outliers(floats(inp))) + \"\\n\"\n\n\ndef check(inp, out, payload):\n    return cmp_multiset(out, _outliers(floats(inp)), tol=1e-6)\n", "q08": "\"\"\"Общие помощники для проверки ответов.\"\"\"\nimport re\n\nNUM_RE = re.compile(r\"[-+]?\\d*\\.?\\d+(?:[eE][-+]?\\d+)?\")\n\n\ndef floats(text):\n    \"\"\"Все числа из текста в виде списка float.\"\"\"\n    return [float(x) for x in NUM_RE.findall(text or \"\")]\n\n\ndef close(a, b, rel=1e-6, abs_=1e-9):\n    return abs(a - b) <= max(abs_, rel * max(abs(a), abs(b)))\n\n\ndef one_number(out):\n    \"\"\"Ровно одно число в выводе. Возвращает (ok, value, msg).\"\"\"\n    got = floats(out)\n    if len(got) != 1:\n        return False, None, f\"ожидалось одно число, найдено {len(got)}\"\n    return True, got[0], \"\"\n\n\ndef cmp_numbers(out, expected, rel=1e-6, abs_=1e-9, names=None):\n    \"\"\"Сравнить последовательность чисел из вывода с эталоном.\"\"\"\n    got = floats(out)\n    if len(got) != len(expected):\n        return False, f\"ожидалось {len(expected)} чисел, получено {len(got)}\"\n    for i, (g, e) in enumerate(zip(got, expected)):\n        if not close(g, e, rel, abs_):\n            name = names[i] if names and i < len(names) else f\"число #{i + 1}\"\n            return False, f\"{name}: ожидалось {e:.6g}, получено {g:.6g}\"\n    return True, \"\"\n\n\ndef cmp_multiset(out, expected, tol=1e-6):\n    \"\"\"Сравнить набор чисел без учёта порядка.\"\"\"\n    got = sorted(floats(out))\n    exp = sorted(expected)\n    if len(got) != len(exp):\n        return False, f\"ожидалось {len(exp)} значений, получено {len(got)}\"\n    for g, e in zip(got, exp):\n        if not close(g, e, 1e-6, tol):\n            return False, f\"значение {g:.6g} не совпало с ожидаемым {e:.6g}\"\n    return True, \"\"\n\n\n\"\"\"q08 — период полураспада через линейную регрессию.\"\"\"\nfrom math import log\n\n\nID = \"q08\"\nTITLE = \"Период полураспада\"\nTOPIC = \"анализ данных\"\nLEVEL = 3\nPOINTS = 30\nSOURCE = \"FAIO-2024, финал, задача C\"\n\nSTATEMENT = \"\"\"\nРадиоактивное вещество теряет половину массы каждые T0 секунд:\n\n    m(t) = m0 * (1/2) ** (t / T0)\n\nДаны n пар измерений (m, t) с небольшим шумом. Восстановите T0.\n\nПодсказка: прологарифмируйте обе части. ln m = ln m0 - (ln 2 / T0) * t —\nэто прямая по t. Найдите её наклон методом наименьших квадратов\n(формула: a = (n*Σxy - Σx*Σy) / (n*Σx^2 - (Σx)^2)) и выразите T0.\n\nВХОД\n  Первая строка: n (число измерений).\n  Далее n строк: два числа m и t.\n\nВЫХОД\n  Одно число T0. Ответ принимается при относительной погрешности не более 1%.\n\nПРИМЕР\n  вход:   5 / 1000 0 / 500 10 / 250 20 / 125 30 / 62.5 40\n  выход:  10.0\n\"\"\"\n\nTEMPLATE = '''import sys\nfrom math import log\n\ndata = sys.stdin.read().split()\nn = int(data[0])\npairs = [(float(data[1 + 2 * i]), float(data[2 + 2 * i])) for i in range(n)]\n\n# ln(m) = ln(m0) - (ln2 / T0) * t  ->  наклон прямой a = -ln2 / T0\n\nprint(T0)\n'''\n\n\ndef gen(rng):\n    m0 = rng.uniform(200, 8000)\n    t0 = rng.uniform(5, 500)\n    n = rng.randint(30, 200)\n    t_max = min(5000, t0 * (log(m0) / log(2)) * 0.9)\n    rows = []\n    for _ in range(n):\n        t = rng.uniform(0, t_max)\n        m = m0 * 0.5 ** (t / t0) * rng.uniform(0.995, 1.005)\n        rows.append(f\"{m:.6f} {t:.6f}\")\n    return f\"{n}\\n\" + \"\\n\".join(rows) + \"\\n\", {\"t0\": t0}\n\n\ndef _fit(inp):\n    data = inp.split()\n    n = int(data[0])\n    xs, ys = [], []\n    for i in range(n):\n        m = float(data[1 + 2 * i])\n        t = float(data[2 + 2 * i])\n        xs.append(t)\n        ys.append(log(m))\n    sx, sy = sum(xs), sum(ys)\n    sxy = sum(x * y for x, y in zip(xs, ys))\n    sxx = sum(x * x for x in xs)\n    slope = (n * sxy - sx * sy) / (n * sxx - sx * sx)\n    return -log(2) / slope\n\n\ndef solve(inp):\n    return f\"{_fit(inp):.6f}\\n\"\n\n\ndef check(inp, out, payload):\n    return cmp_numbers(out, [payload[\"t0\"]], rel=0.01, abs_=1e-9, names=[\"период полураспада\"])\n", "q09": "\"\"\"Общие помощники для проверки ответов.\"\"\"\nimport re\n\nNUM_RE = re.compile(r\"[-+]?\\d*\\.?\\d+(?:[eE][-+]?\\d+)?\")\n\n\ndef floats(text):\n    \"\"\"Все числа из текста в виде списка float.\"\"\"\n    return [float(x) for x in NUM_RE.findall(text or \"\")]\n\n\ndef close(a, b, rel=1e-6, abs_=1e-9):\n    return abs(a - b) <= max(abs_, rel * max(abs(a), abs(b)))\n\n\ndef one_number(out):\n    \"\"\"Ровно одно число в выводе. Возвращает (ok, value, msg).\"\"\"\n    got = floats(out)\n    if len(got) != 1:\n        return False, None, f\"ожидалось одно число, найдено {len(got)}\"\n    return True, got[0], \"\"\n\n\ndef cmp_numbers(out, expected, rel=1e-6, abs_=1e-9, names=None):\n    \"\"\"Сравнить последовательность чисел из вывода с эталоном.\"\"\"\n    got = floats(out)\n    if len(got) != len(expected):\n        return False, f\"ожидалось {len(expected)} чисел, получено {len(got)}\"\n    for i, (g, e) in enumerate(zip(got, expected)):\n        if not close(g, e, rel, abs_):\n            name = names[i] if names and i < len(names) else f\"число #{i + 1}\"\n            return False, f\"{name}: ожидалось {e:.6g}, получено {g:.6g}\"\n    return True, \"\"\n\n\ndef cmp_multiset(out, expected, tol=1e-6):\n    \"\"\"Сравнить набор чисел без учёта порядка.\"\"\"\n    got = sorted(floats(out))\n    exp = sorted(expected)\n    if len(got) != len(exp):\n        return False, f\"ожидалось {len(exp)} значений, получено {len(got)}\"\n    for g, e in zip(got, exp):\n        if not close(g, e, 1e-6, tol):\n            return False, f\"значение {g:.6g} не совпало с ожидаемым {e:.6g}\"\n    return True, \"\"\n\n\n\"\"\"q09 — умножение матриц.\"\"\"\n\n\nID = \"q09\"\nTITLE = \"Гравитационная матрица\"\nTOPIC = \"анализ данных\"\nLEVEL = 2\nPOINTS = 20\nSOURCE = \"FAIO-2024, отбор, задача F\"\n\nSTATEMENT = \"\"\"\nДаны две матрицы: первая размера a x b, вторая размера b x c.\nВыведите их произведение — матрицу a x c.\n\nНапоминание: элемент (i, j) произведения равен сумме произведений\ni-й строки первой матрицы на j-й столбец второй.\n\nВХОД\n  Первая строка: три натуральных числа a, b, c.\n  Далее a строк по b чисел — первая матрица.\n  Далее b строк по c чисел — вторая матрица.\n\nВЫХОД\n  a строк по c чисел — произведение.\n\nПРИМЕР\n  вход:   2 2 2 / 1 2 / 3 4 / 5 6 / 7 8\n  выход:  19 22 / 43 50\n\"\"\"\n\nTEMPLATE = '''import sys\n\ndata = sys.stdin.read().split()\npos = 0\na, b, c = int(data[0]), int(data[1]), int(data[2])\npos = 3\n\nA = []\nfor i in range(a):\n    A.append([float(x) for x in data[pos:pos + b]])\n    pos += b\n\nB = []\nfor i in range(b):\n    B.append([float(x) for x in data[pos:pos + c]])\n    pos += c\n\nfor i in range(a):\n    row = []\n    for j in range(c):\n        row.append(...)\n    print(\" \".join(str(v) for v in row))\n'''\n\n\ndef _product(inp):\n    data = inp.split()\n    a, b, c = int(data[0]), int(data[1]), int(data[2])\n    pos = 3\n    A, B = [], []\n    for _ in range(a):\n        A.append([float(x) for x in data[pos:pos + b]])\n        pos += b\n    for _ in range(b):\n        B.append([float(x) for x in data[pos:pos + c]])\n        pos += c\n    return [[sum(A[i][k] * B[k][j] for k in range(b)) for j in range(c)] for i in range(a)]\n\n\ndef gen(rng):\n    a, b, c = rng.randint(1, 6), rng.randint(1, 6), rng.randint(1, 6)\n    lines = [f\"{a} {b} {c}\"]\n    for _ in range(a):\n        lines.append(\" \".join(str(rng.randint(-9, 9)) for _ in range(b)))\n    for _ in range(b):\n        lines.append(\" \".join(str(rng.randint(-9, 9)) for _ in range(c)))\n    return \"\\n\".join(lines) + \"\\n\", {}\n\n\ndef solve(inp):\n    return \"\\n\".join(\" \".join(f\"{v:.6f}\" for v in row) for row in _product(inp)) + \"\\n\"\n\n\ndef check(inp, out, payload):\n    expected = [v for row in _product(inp) for v in row]\n    return cmp_numbers(out, expected, rel=1e-6, abs_=1e-6)\n", "q10": "\"\"\"Общие помощники для проверки ответов.\"\"\"\nimport re\n\nNUM_RE = re.compile(r\"[-+]?\\d*\\.?\\d+(?:[eE][-+]?\\d+)?\")\n\n\ndef floats(text):\n    \"\"\"Все числа из текста в виде списка float.\"\"\"\n    return [float(x) for x in NUM_RE.findall(text or \"\")]\n\n\ndef close(a, b, rel=1e-6, abs_=1e-9):\n    return abs(a - b) <= max(abs_, rel * max(abs(a), abs(b)))\n\n\ndef one_number(out):\n    \"\"\"Ровно одно число в выводе. Возвращает (ok, value, msg).\"\"\"\n    got = floats(out)\n    if len(got) != 1:\n        return False, None, f\"ожидалось одно число, найдено {len(got)}\"\n    return True, got[0], \"\"\n\n\ndef cmp_numbers(out, expected, rel=1e-6, abs_=1e-9, names=None):\n    \"\"\"Сравнить последовательность чисел из вывода с эталоном.\"\"\"\n    got = floats(out)\n    if len(got) != len(expected):\n        return False, f\"ожидалось {len(expected)} чисел, получено {len(got)}\"\n    for i, (g, e) in enumerate(zip(got, expected)):\n        if not close(g, e, rel, abs_):\n            name = names[i] if names and i < len(names) else f\"число #{i + 1}\"\n            return False, f\"{name}: ожидалось {e:.6g}, получено {g:.6g}\"\n    return True, \"\"\n\n\ndef cmp_multiset(out, expected, tol=1e-6):\n    \"\"\"Сравнить набор чисел без учёта порядка.\"\"\"\n    got = sorted(floats(out))\n    exp = sorted(expected)\n    if len(got) != len(exp):\n        return False, f\"ожидалось {len(exp)} значений, получено {len(got)}\"\n    for g, e in zip(got, exp):\n        if not close(g, e, 1e-6, tol):\n            return False, f\"значение {g:.6g} не совпало с ожидаемым {e:.6g}\"\n    return True, \"\"\n\n\n\"\"\"q10 — парабола по трём точкам и производная.\"\"\"\n\n\nID = \"q10\"\nTITLE = \"Скорость ракеты\"\nTOPIC = \"алгоритмы\"\nLEVEL = 2\nPOINTS = 20\nSOURCE = \"FAIO-2024, отбор, задачи C и D\"\n\nSTATEMENT = \"\"\"\nГрафик «время — расстояние» ракеты является параболой y = a*x^2 + b*x + c.\nДатчик успел записать три точки, но описал их запутанно:\n\n  - первая точка имеет координаты (x1, y1);\n  - вторая точка ЛЕВЕЕ первой на x2 и ВЫШЕ третьей на y2,\n    то есть её координаты (x1 - x2, y3 + y2);\n  - третья точка имеет координаты (x3, y3).\n\nВосстановите коэффициенты a, b, c, а затем найдите скорость ракеты\nв момент времени d (скорость — производная расстояния по времени).\n\nВХОД\n  Одна строка: семь вещественных чисел x1 y1 x2 y2 x3 y3 d.\n\nВЫХОД\n  Четыре числа через пробел: a b c v, где v — скорость в момент d.\n\nПРИМЕР\n  вход:   1 6 2 1 0 1 2\n  выход:  2 3 1 11\n\"\"\"\n\nTEMPLATE = '''import sys\n\nx1, y1, x2, y2, x3, y3, d = [float(v) for v in sys.stdin.read().split()]\n\n# три точки параболы\npoints = [(x1, y1), (x1 - x2, y3 + y2), (x3, y3)]\n\n# решите систему из трёх уравнений a*x^2 + b*x + c = y\n# (метод Гаусса или формулы Крамера)\n\nv = 2 * a * d + b\nprint(a, b, c, v)\n'''\n\n\ndef _solve3(points):\n    \"\"\"Решает систему для параболы через три точки методом Крамера.\"\"\"\n    (xa, ya), (xb, yb), (xc, yc) = points\n\n    def det(m):\n        return (m[0][0] * (m[1][1] * m[2][2] - m[1][2] * m[2][1])\n                - m[0][1] * (m[1][0] * m[2][2] - m[1][2] * m[2][0])\n                + m[0][2] * (m[1][0] * m[2][1] - m[1][1] * m[2][0]))\n\n    base = [[xa * xa, xa, 1], [xb * xb, xb, 1], [xc * xc, xc, 1]]\n    ys = [ya, yb, yc]\n    d0 = det(base)\n    out = []\n    for col in range(3):\n        m = [row[:] for row in base]\n        for r in range(3):\n            m[r][col] = ys[r]\n        out.append(det(m) / d0)\n    return out\n\n\ndef gen(rng):\n    a = rng.choice([-3, -2, -1, 1, 2, 3]) + round(rng.uniform(-0.5, 0.5), 2)\n    b = round(rng.uniform(-10, 10), 2)\n    c = round(rng.uniform(-20, 20), 2)\n    xs = rng.sample([round(v * 0.5, 1) for v in range(-20, 21)], 3)\n    x1, xm, x3 = xs\n    f = lambda x: a * x * x + b * x + c\n    y1, ym, y3 = f(x1), f(xm), f(x3)\n    x2 = x1 - xm\n    y2 = ym - y3\n    d = round(rng.uniform(1, 20), 2)\n    inp = f\"{x1} {y1:.6f} {x2} {y2:.6f} {x3} {y3:.6f} {d}\\n\"\n    return inp, {\"a\": a, \"b\": b, \"c\": c, \"v\": 2 * a * d + b}\n\n\ndef solve(inp):\n    x1, y1, x2, y2, x3, y3, d = [float(v) for v in inp.split()]\n    a, b, c = _solve3([(x1, y1), (x1 - x2, y3 + y2), (x3, y3)])\n    return f\"{a:.6f} {b:.6f} {c:.6f} {2 * a * d + b:.6f}\\n\"\n\n\ndef check(inp, out, payload):\n    exp = [payload[\"a\"], payload[\"b\"], payload[\"c\"], payload[\"v\"]]\n    return cmp_numbers(out, exp, rel=1e-3, abs_=1e-3, names=[\"a\", \"b\", \"c\", \"скорость\"])\n", "q11": "\"\"\"Общие помощники для проверки ответов.\"\"\"\nimport re\n\nNUM_RE = re.compile(r\"[-+]?\\d*\\.?\\d+(?:[eE][-+]?\\d+)?\")\n\n\ndef floats(text):\n    \"\"\"Все числа из текста в виде списка float.\"\"\"\n    return [float(x) for x in NUM_RE.findall(text or \"\")]\n\n\ndef close(a, b, rel=1e-6, abs_=1e-9):\n    return abs(a - b) <= max(abs_, rel * max(abs(a), abs(b)))\n\n\ndef one_number(out):\n    \"\"\"Ровно одно число в выводе. Возвращает (ok, value, msg).\"\"\"\n    got = floats(out)\n    if len(got) != 1:\n        return False, None, f\"ожидалось одно число, найдено {len(got)}\"\n    return True, got[0], \"\"\n\n\ndef cmp_numbers(out, expected, rel=1e-6, abs_=1e-9, names=None):\n    \"\"\"Сравнить последовательность чисел из вывода с эталоном.\"\"\"\n    got = floats(out)\n    if len(got) != len(expected):\n        return False, f\"ожидалось {len(expected)} чисел, получено {len(got)}\"\n    for i, (g, e) in enumerate(zip(got, expected)):\n        if not close(g, e, rel, abs_):\n            name = names[i] if names and i < len(names) else f\"число #{i + 1}\"\n            return False, f\"{name}: ожидалось {e:.6g}, получено {g:.6g}\"\n    return True, \"\"\n\n\ndef cmp_multiset(out, expected, tol=1e-6):\n    \"\"\"Сравнить набор чисел без учёта порядка.\"\"\"\n    got = sorted(floats(out))\n    exp = sorted(expected)\n    if len(got) != len(exp):\n        return False, f\"ожидалось {len(exp)} значений, получено {len(got)}\"\n    for g, e in zip(got, exp):\n        if not close(g, e, 1e-6, tol):\n            return False, f\"значение {g:.6g} не совпало с ожидаемым {e:.6g}\"\n    return True, \"\"\n\n\n\"\"\"q11 — случайное блуждание по графу (марковская цепь).\"\"\"\n\n\nID = \"q11\"\nTITLE = \"Рэй бегает по станции\"\nTOPIC = \"алгоритмы\"\nLEVEL = 3\nPOINTS = 30\nSOURCE = \"FAIO-2024, отбор, задача E\"\n\nSTATEMENT = \"\"\"\nКосмическая станция — это граф из n вершин и m коридоров (рёбер).\nРэй стартует в вершине 0. Каждую минуту он выбирает РАВНОВЕРОЯТНО один\nиз коридоров, выходящих из текущей вершины, и переходит по нему.\nОн не останавливается и не пропускает ходы.\n\nНайдите вероятность того, что ровно через k минут Рэй окажется в вершине t.\n\nПодсказка: заведите массив вероятностей по вершинам и k раз пересчитайте его:\nновая вероятность вершины = сумма по соседям (вероятность соседа / его степень).\n\nВХОД\n  Первая строка: четыре целых числа n, m, t, k.\n  Далее m строк: по два числа u v — коридор между вершинами u и v\n  (граф неориентированный, петель и кратных рёбер нет).\n\nВЫХОД\n  Одно число — вероятность, не менее шести знаков после запятой.\n\nПРИМЕР\n  вход:   3 3 2 2 / 0 1 / 1 2 / 0 2\n  выход:  0.500000\n\"\"\"\n\nTEMPLATE = '''import sys\n\ndata = sys.stdin.read().split()\nn, m, t, k = (int(data[i]) for i in range(4))\n\nadj = [[] for _ in range(n)]\npos = 4\nfor _ in range(m):\n    u, v = int(data[pos]), int(data[pos + 1])\n    pos += 2\n    adj[u].append(v)\n    adj[v].append(u)\n\nprob = [0.0] * n\nprob[0] = 1.0\nfor step in range(k):\n    new = [0.0] * n\n    # ...\n    prob = new\n\nprint(f\"{prob[t]:.6f}\")\n'''\n\n\ndef _walk(inp):\n    data = inp.split()\n    n, m, t, k = (int(data[i]) for i in range(4))\n    adj = [[] for _ in range(n)]\n    pos = 4\n    for _ in range(m):\n        u, v = int(data[pos]), int(data[pos + 1])\n        pos += 2\n        adj[u].append(v)\n        adj[v].append(u)\n    prob = [0.0] * n\n    prob[0] = 1.0\n    for _ in range(k):\n        new = [0.0] * n\n        for u in range(n):\n            if prob[u] and adj[u]:\n                share = prob[u] / len(adj[u])\n                for v in adj[u]:\n                    new[v] += share\n        prob = new\n    return prob[t]\n\n\ndef gen(rng):\n    n = rng.randint(6, 11)\n    edges = set()\n    # остовное дерево гарантирует связность\n    for v in range(1, n):\n        u = rng.randrange(v)\n        edges.add((min(u, v), max(u, v)))\n    extra = rng.randint(1, n)\n    attempts = 0\n    while extra > 0 and attempts < 100:\n        attempts += 1\n        u, v = rng.randrange(n), rng.randrange(n)\n        if u != v and (min(u, v), max(u, v)) not in edges:\n            edges.add((min(u, v), max(u, v)))\n            extra -= 1\n    edges = sorted(edges)\n    t = rng.randrange(n)\n    k = rng.randint(2, 6)\n    lines = [f\"{n} {len(edges)} {t} {k}\"] + [f\"{u} {v}\" for u, v in edges]\n    return \"\\n\".join(lines) + \"\\n\", {}\n\n\ndef solve(inp):\n    return f\"{_walk(inp):.6f}\\n\"\n\n\ndef check(inp, out, payload):\n    return cmp_numbers(out, [_walk(inp)], rel=1e-5, abs_=1e-6, names=[\"вероятность\"])\n", "q12": "\"\"\"Общие помощники для проверки ответов.\"\"\"\nimport re\n\nNUM_RE = re.compile(r\"[-+]?\\d*\\.?\\d+(?:[eE][-+]?\\d+)?\")\n\n\ndef floats(text):\n    \"\"\"Все числа из текста в виде списка float.\"\"\"\n    return [float(x) for x in NUM_RE.findall(text or \"\")]\n\n\ndef close(a, b, rel=1e-6, abs_=1e-9):\n    return abs(a - b) <= max(abs_, rel * max(abs(a), abs(b)))\n\n\ndef one_number(out):\n    \"\"\"Ровно одно число в выводе. Возвращает (ok, value, msg).\"\"\"\n    got = floats(out)\n    if len(got) != 1:\n        return False, None, f\"ожидалось одно число, найдено {len(got)}\"\n    return True, got[0], \"\"\n\n\ndef cmp_numbers(out, expected, rel=1e-6, abs_=1e-9, names=None):\n    \"\"\"Сравнить последовательность чисел из вывода с эталоном.\"\"\"\n    got = floats(out)\n    if len(got) != len(expected):\n        return False, f\"ожидалось {len(expected)} чисел, получено {len(got)}\"\n    for i, (g, e) in enumerate(zip(got, expected)):\n        if not close(g, e, rel, abs_):\n            name = names[i] if names and i < len(names) else f\"число #{i + 1}\"\n            return False, f\"{name}: ожидалось {e:.6g}, получено {g:.6g}\"\n    return True, \"\"\n\n\ndef cmp_multiset(out, expected, tol=1e-6):\n    \"\"\"Сравнить набор чисел без учёта порядка.\"\"\"\n    got = sorted(floats(out))\n    exp = sorted(expected)\n    if len(got) != len(exp):\n        return False, f\"ожидалось {len(exp)} значений, получено {len(got)}\"\n    for g, e in zip(got, exp):\n        if not close(g, e, 1e-6, tol):\n            return False, f\"значение {g:.6g} не совпало с ожидаемым {e:.6g}\"\n    return True, \"\"\n\n\n\"\"\"q12 — кластеризация k-means.\"\"\"\n\n\nID = \"q12\"\nTITLE = \"K-means своими руками\"\nTOPIC = \"машинное обучение\"\nLEVEL = 3\nPOINTS = 30\nSOURCE = \"FAIO-2024, финал, задача D\"\n\nSTATEMENT = \"\"\"\nРеализуйте алгоритм k-средних (k-means) с ЗАДАННЫМИ начальными центроидами.\n\nАлгоритм:\n  1) каждую точку относим к ближайшему центроиду (расстояние евклидово;\n     при равенстве расстояний берём центроид с меньшим номером);\n  2) каждый центроид переносим в среднее своих точек;\n     если к центроиду не попала ни одна точка — оставляем его на месте;\n  3) повторяем шаги 1-2, пока центроиды не перестанут меняться\n     (или до 300 итераций).\n\nВХОД\n  Первая строка: n — число точек.\n  Далее n строк: координаты x y.\n  Затем строка: k — число центроидов.\n  Далее k строк: начальные координаты центроидов.\n\nВЫХОД\n  k строк по два числа — итоговые координаты центроидов\n  (в том же порядке, в каком даны начальные).\n\nОЦЕНКА\n  Ответ принимается, если итоговая функция потерь\n  L = (1/n) * сумма квадратов расстояний до ближайшего центроида\n  не хуже авторского решения.\n\"\"\"\n\nTEMPLATE = '''import sys\n\ndata = sys.stdin.read().split()\npos = 0\nn = int(data[pos]); pos += 1\npoints = []\nfor _ in range(n):\n    points.append((float(data[pos]), float(data[pos + 1])))\n    pos += 2\nk = int(data[pos]); pos += 1\ncent = []\nfor _ in range(k):\n    cent.append([float(data[pos]), float(data[pos + 1])])\n    pos += 2\n\nfor step in range(300):\n    groups = [[] for _ in range(k)]\n    for (x, y) in points:\n        # найти ближайший центроид и положить точку в его группу\n        ...\n    # пересчитать центроиды; если группа пустая — оставить центроид как есть\n    ...\n\nfor cx, cy in cent:\n    print(cx, cy)\n'''\n\n\ndef _parse(inp):\n    data = inp.split()\n    pos = 0\n    n = int(data[pos]); pos += 1\n    points = []\n    for _ in range(n):\n        points.append((float(data[pos]), float(data[pos + 1])))\n        pos += 2\n    k = int(data[pos]); pos += 1\n    cent = []\n    for _ in range(k):\n        cent.append([float(data[pos]), float(data[pos + 1])])\n        pos += 2\n    return points, cent\n\n\ndef _loss(points, cent):\n    total = 0.0\n    for x, y in points:\n        total += min((x - cx) ** 2 + (y - cy) ** 2 for cx, cy in cent)\n    return total / len(points)\n\n\ndef _kmeans(points, cent):\n    cent = [list(c) for c in cent]\n    for _ in range(300):\n        groups = [[] for _ in cent]\n        for x, y in points:\n            best, bd = 0, None\n            for i, (cx, cy) in enumerate(cent):\n                d = (x - cx) ** 2 + (y - cy) ** 2\n                if bd is None or d < bd - 1e-12:\n                    best, bd = i, d\n            groups[best].append((x, y))\n        moved = False\n        for i, g in enumerate(groups):\n            if not g:\n                continue\n            nx = sum(p[0] for p in g) / len(g)\n            ny = sum(p[1] for p in g) / len(g)\n            if abs(nx - cent[i][0]) > 1e-12 or abs(ny - cent[i][1]) > 1e-12:\n                moved = True\n            cent[i] = [nx, ny]\n        if not moved:\n            break\n    return cent\n\n\ndef gen(rng):\n    k = rng.randint(2, 4)\n    centers = []\n    while len(centers) < k:\n        c = (rng.uniform(5, 45), rng.uniform(5, 45))\n        if all((c[0] - o[0]) ** 2 + (c[1] - o[1]) ** 2 > 15 ** 2 for o in centers):\n            centers.append(c)\n    points = []\n    for cx, cy in centers:\n        for _ in range(rng.randint(25, 60)):\n            points.append((round(cx + rng.gauss(0, 2), 4), round(cy + rng.gauss(0, 2), 4)))\n    rng.shuffle(points)\n    start = rng.sample(points, k)\n    lines = [str(len(points))]\n    lines += [f\"{x} {y}\" for x, y in points]\n    lines.append(str(k))\n    lines += [f\"{x} {y}\" for x, y in start]\n    return \"\\n\".join(lines) + \"\\n\", {}\n\n\ndef solve(inp):\n    points, cent = _parse(inp)\n    return \"\\n\".join(f\"{cx:.6f} {cy:.6f}\" for cx, cy in _kmeans(points, cent)) + \"\\n\"\n\n\ndef check(inp, out, payload):\n    points, cent = _parse(inp)\n    k = len(cent)\n    got = floats(out)\n    if len(got) != 2 * k:\n        return False, f\"ожидалось {k} пар координат, получено {len(got) // 2}\"\n    student = [[got[2 * i], got[2 * i + 1]] for i in range(k)]\n    ref = _kmeans(points, cent)\n    ls, lr = _loss(points, student), _loss(points, ref)\n    if ls <= lr * 1.0001 + 1e-9:\n        return True, \"\"\n    return False, f\"функция потерь {ls:.4f} хуже авторской {lr:.4f}\"\n", "q13": "\"\"\"Общие помощники для проверки ответов.\"\"\"\nimport re\n\nNUM_RE = re.compile(r\"[-+]?\\d*\\.?\\d+(?:[eE][-+]?\\d+)?\")\n\n\ndef floats(text):\n    \"\"\"Все числа из текста в виде списка float.\"\"\"\n    return [float(x) for x in NUM_RE.findall(text or \"\")]\n\n\ndef close(a, b, rel=1e-6, abs_=1e-9):\n    return abs(a - b) <= max(abs_, rel * max(abs(a), abs(b)))\n\n\ndef one_number(out):\n    \"\"\"Ровно одно число в выводе. Возвращает (ok, value, msg).\"\"\"\n    got = floats(out)\n    if len(got) != 1:\n        return False, None, f\"ожидалось одно число, найдено {len(got)}\"\n    return True, got[0], \"\"\n\n\ndef cmp_numbers(out, expected, rel=1e-6, abs_=1e-9, names=None):\n    \"\"\"Сравнить последовательность чисел из вывода с эталоном.\"\"\"\n    got = floats(out)\n    if len(got) != len(expected):\n        return False, f\"ожидалось {len(expected)} чисел, получено {len(got)}\"\n    for i, (g, e) in enumerate(zip(got, expected)):\n        if not close(g, e, rel, abs_):\n            name = names[i] if names and i < len(names) else f\"число #{i + 1}\"\n            return False, f\"{name}: ожидалось {e:.6g}, получено {g:.6g}\"\n    return True, \"\"\n\n\ndef cmp_multiset(out, expected, tol=1e-6):\n    \"\"\"Сравнить набор чисел без учёта порядка.\"\"\"\n    got = sorted(floats(out))\n    exp = sorted(expected)\n    if len(got) != len(exp):\n        return False, f\"ожидалось {len(exp)} значений, получено {len(got)}\"\n    for g, e in zip(got, exp):\n        if not close(g, e, 1e-6, tol):\n            return False, f\"значение {g:.6g} не совпало с ожидаемым {e:.6g}\"\n    return True, \"\"\n\n\n\"\"\"q13 — определение языка текста (мини-версия задачи FAIO-2025).\"\"\"\nimport math\nfrom collections import defaultdict\n\nID = \"q13\"\nTITLE = \"Кто на каком языке говорит\"\nTOPIC = \"машинное обучение\"\nLEVEL = 3\nPOINTS = 30\nSOURCE = \"FAIO-2025, отбор, задача 4\"\n\nSTATEMENT = \"\"\"\nЧат-бот телеком-оператора получает сообщения на трёх языках: казахском (kaz),\nрусском (ru) и английском (eng). Нужно определить язык каждого сообщения.\n\nВам дана обучающая выборка с известными метками и тестовая выборка без них.\nВнимание: примерно в каждом восьмом сообщении есть вкрапления слов из другого\nязыка — модель должна смотреть на текст целиком, а не на одно слово.\n\nПодсказка: сильный и простой бейзлайн — наивный байесовский классификатор\nна символьных n-граммах. Для каждого языка посчитайте, сколько раз встречается\nкаждая n-грамма, а дальше сравните логарифмы вероятностей. Внешние библиотеки\nне нужны, хватает словарей.\n\nВХОД\n  Первая строка: два числа n_train и n_test.\n  Далее n_train строк: метка, символ табуляции, текст.\n  Далее n_test строк: только текст.\n\nВЫХОД\n  n_test строк: предсказанная метка (kaz, ru или eng) для каждого тестового\n  текста, в том же порядке.\n\nОЦЕНКА\n  Ответ принимается при доле правильных ответов не ниже 0.85.\n\"\"\"\n\nTEMPLATE = '''import sys\nfrom collections import defaultdict\n\nlines = sys.stdin.read().split(\"\\\\n\")\nn_train, n_test = (int(v) for v in lines[0].split())\n\ntrain = []\nfor i in range(1, n_train + 1):\n    label, text = lines[i].split(\"\\\\t\")\n    train.append((label, text))\n\ntest = [lines[1 + n_train + i] for i in range(n_test)]\n\n\ndef ngrams(text, n=3):\n    text = \" \" + text.lower() + \" \"\n    return [text[i:i + n] for i in range(len(text) - n + 1)]\n\n\n# 1) посчитайте частоты n-грамм для каждого языка\n# 2) для каждого тестового текста сложите log((count + 1) / (total + V))\n# 3) выберите язык с наибольшей суммой\n\nfor text in test:\n    print(best_label)\n'''\n\n_SYL = {\n    \"kaz\": [\"қа\", \"ған\", \"ері\", \"ңіз\", \"дық\", \"жа\", \"мен\", \"тұр\", \"әде\", \"ғыс\",\n            \"ұлы\", \"өзі\", \"іст\", \"бол\", \"лар\", \"тын\", \"сын\"],\n    \"ru\": [\"по\", \"что\", \"ени\", \"ость\", \"ый\", \"ова\", \"при\", \"ний\", \"сть\", \"ла\",\n           \"ко\", \"ра\", \"де\", \"ств\", \"тель\", \"ние\"],\n    \"eng\": [\"the\", \"ing\", \"tion\", \"and\", \"ou\", \"ea\", \"sh\", \"wh\", \"ly\", \"er\",\n            \"st\", \"al\", \"ment\", \"pro\", \"con\"],\n}\n_LABELS = [\"kaz\", \"ru\", \"eng\"]\n\n\ndef _word(rng, lang):\n    return \"\".join(rng.choice(_SYL[lang]) for _ in range(rng.randint(2, 4)))\n\n\ndef _text(rng, lang):\n    words = [_word(rng, lang) for _ in range(rng.randint(4, 10))]\n    if rng.random() < 0.12:  # вкрапления чужого языка\n        other = rng.choice([l for l in _LABELS if l != lang])\n        for _ in range(rng.randint(1, 2)):\n            words[rng.randrange(len(words))] = _word(rng, other)\n    return \" \".join(words)\n\n\ndef gen(rng):\n    n_train, n_test = 300, 120\n    lines = [f\"{n_train} {n_test}\"]\n    for _ in range(n_train):\n        lang = rng.choice(_LABELS)\n        lines.append(f\"{lang}\\t{_text(rng, lang)}\")\n    answers = []\n    for _ in range(n_test):\n        lang = rng.choice(_LABELS)\n        answers.append(lang)\n        lines.append(_text(rng, lang))\n    return \"\\n\".join(lines) + \"\\n\", {\"answers\": answers}\n\n\ndef _parse(inp):\n    lines = inp.split(\"\\n\")\n    n_train, n_test = (int(v) for v in lines[0].split())\n    train = []\n    for i in range(1, n_train + 1):\n        label, text = lines[i].split(\"\\t\")\n        train.append((label, text))\n    test = [lines[1 + n_train + i] for i in range(n_test)]\n    return train, test\n\n\ndef _ngrams(text, n=3):\n    text = \" \" + text.lower() + \" \"\n    return [text[i:i + n] for i in range(len(text) - n + 1)]\n\n\ndef solve(inp):\n    train, test = _parse(inp)\n    counts = {l: defaultdict(int) for l in _LABELS}\n    totals = {l: 0 for l in _LABELS}\n    vocab = set()\n    for label, text in train:\n        for g in _ngrams(text):\n            counts[label][g] += 1\n            totals[label] += 1\n            vocab.add(g)\n    v = len(vocab) + 1\n    out = []\n    for text in test:\n        grams = _ngrams(text)\n        best, best_score = None, None\n        for label in _LABELS:\n            score = 0.0\n            for g in grams:\n                score += math.log((counts[label][g] + 1) / (totals[label] + v))\n            if best_score is None or score > best_score:\n                best, best_score = label, score\n        out.append(best)\n    return \"\\n\".join(out) + \"\\n\"\n\n\ndef check(inp, out, payload):\n    answers = payload[\"answers\"]\n    got = [line.strip() for line in (out or \"\").strip().split(\"\\n\") if line.strip()]\n    if len(got) != len(answers):\n        return False, f\"ожидалось {len(answers)} строк, получено {len(got)}\"\n    bad = [g for g in got if g not in _LABELS]\n    if bad:\n        return False, f\"недопустимая метка: {bad[0]!r} (нужны kaz, ru, eng)\"\n    acc = sum(g == a for g, a in zip(got, answers)) / len(answers)\n    if acc >= 0.85:\n        return True, f\"точность {acc:.3f}\"\n    return False, f\"точность {acc:.3f}, а нужно не меньше 0.850\"\n", "q14": "\"\"\"Общие помощники для проверки ответов.\"\"\"\nimport re\n\nNUM_RE = re.compile(r\"[-+]?\\d*\\.?\\d+(?:[eE][-+]?\\d+)?\")\n\n\ndef floats(text):\n    \"\"\"Все числа из текста в виде списка float.\"\"\"\n    return [float(x) for x in NUM_RE.findall(text or \"\")]\n\n\ndef close(a, b, rel=1e-6, abs_=1e-9):\n    return abs(a - b) <= max(abs_, rel * max(abs(a), abs(b)))\n\n\ndef one_number(out):\n    \"\"\"Ровно одно число в выводе. Возвращает (ok, value, msg).\"\"\"\n    got = floats(out)\n    if len(got) != 1:\n        return False, None, f\"ожидалось одно число, найдено {len(got)}\"\n    return True, got[0], \"\"\n\n\ndef cmp_numbers(out, expected, rel=1e-6, abs_=1e-9, names=None):\n    \"\"\"Сравнить последовательность чисел из вывода с эталоном.\"\"\"\n    got = floats(out)\n    if len(got) != len(expected):\n        return False, f\"ожидалось {len(expected)} чисел, получено {len(got)}\"\n    for i, (g, e) in enumerate(zip(got, expected)):\n        if not close(g, e, rel, abs_):\n            name = names[i] if names and i < len(names) else f\"число #{i + 1}\"\n            return False, f\"{name}: ожидалось {e:.6g}, получено {g:.6g}\"\n    return True, \"\"\n\n\ndef cmp_multiset(out, expected, tol=1e-6):\n    \"\"\"Сравнить набор чисел без учёта порядка.\"\"\"\n    got = sorted(floats(out))\n    exp = sorted(expected)\n    if len(got) != len(exp):\n        return False, f\"ожидалось {len(exp)} значений, получено {len(got)}\"\n    for g, e in zip(got, exp):\n        if not close(g, e, 1e-6, tol):\n            return False, f\"значение {g:.6g} не совпало с ожидаемым {e:.6g}\"\n    return True, \"\"\n\n\n\"\"\"q14 — разделяющая прямая (упрощённый SVM).\"\"\"\n\n\nID = \"q14\"\nTITLE = \"Разделяющая прямая\"\nTOPIC = \"машинное обучение\"\nLEVEL = 3\nPOINTS = 30\nSOURCE = \"FAIO-2024, финал, задача F (SVM)\"\n\nSTATEMENT = \"\"\"\nНа плоскости даны k точек, каждая принадлежит одному из двух классов\n(метка +1 или -1). Гарантируется, что классы разделимы прямой.\n\nНайдите коэффициенты a, b, c прямой a*x + b*y + c = 0, которая их разделяет.\nТочка классифицируется так:\n    если a*x + b*y + c >= 0, то класс +1, иначе класс -1.\n\nПодсказка: подойдёт любой линейный классификатор. Самый простой —\nперсептрон: начните с нулевых a, b, c и, пока есть ошибки, для каждой\nневерно классифицированной точки делайте\n    a += l * x,   b += l * y,   c += l\nгде l — истинная метка точки. Для разделимых данных это сходится.\n\nВХОД\n  Первая строка: k — число точек.\n  Далее k строк: три числа x y l.\n\nВЫХОД\n  Три числа через пробел: a b c.\n\nОЦЕНКА\n  Ответ принимается, если доля верно классифицированных точек не ниже 0.97.\n\"\"\"\n\nTEMPLATE = '''import sys\n\ndata = sys.stdin.read().split()\nk = int(data[0])\npts = []\nfor i in range(k):\n    x = float(data[1 + 3 * i])\n    y = float(data[2 + 3 * i])\n    l = float(data[3 + 3 * i])\n    pts.append((x, y, l))\n\na = b = c = 0.0\nfor epoch in range(200):\n    errors = 0\n    for x, y, l in pts:\n        pred = 1 if a * x + b * y + c >= 0 else -1\n        if pred != l:\n            ...\n            errors += 1\n    if errors == 0:\n        break\n\nprint(a, b, c)\n'''\n\n\ndef _parse(inp):\n    data = inp.split()\n    k = int(data[0])\n    pts = []\n    for i in range(k):\n        pts.append((float(data[1 + 3 * i]), float(data[2 + 3 * i]), float(data[3 + 3 * i])))\n    return pts\n\n\ndef gen(rng):\n    k = rng.randint(200, 400)\n    a = rng.uniform(-1, 1) or 0.5\n    b = rng.uniform(-1, 1) or 0.5\n    norm = (a * a + b * b) ** 0.5\n    a, b = a / norm, b / norm\n    c = rng.uniform(-30, 30)\n    margin = rng.uniform(3, 8)\n    lines = [str(k)]\n    for _ in range(k):\n        while True:\n            x = rng.uniform(-100, 100)\n            y = rng.uniform(-100, 100)\n            d = a * x + b * y + c\n            if abs(d) >= margin:\n                break\n        label = 1 if d > 0 else -1\n        lines.append(f\"{x:.4f} {y:.4f} {label}\")\n    return \"\\n\".join(lines) + \"\\n\", {}\n\n\ndef _accuracy(pts, a, b, c):\n    ok = 0\n    for x, y, l in pts:\n        pred = 1 if a * x + b * y + c >= 0 else -1\n        ok += (pred == l)\n    return ok / len(pts)\n\n\ndef solve(inp):\n    pts = _parse(inp)\n    a = b = c = 0.0\n    for _ in range(400):\n        errors = 0\n        for x, y, l in pts:\n            pred = 1 if a * x + b * y + c >= 0 else -1\n            if pred != l:\n                a += l * x\n                b += l * y\n                c += l\n                errors += 1\n        if errors == 0:\n            break\n    return f\"{a:.6f} {b:.6f} {c:.6f}\\n\"\n\n\ndef check(inp, out, payload):\n    got = floats(out)\n    if len(got) != 3:\n        return False, f\"ожидалось три числа a b c, получено {len(got)}\"\n    a, b, c = got\n    if a == 0 and b == 0:\n        return False, \"прямая вырождена: a и b не могут быть нулями одновременно\"\n    acc = _accuracy(_parse(inp), a, b, c)\n    if acc >= 0.97:\n        return True, f\"точность {acc:.4f}\"\n    return False, f\"точность {acc:.4f}, а нужно не меньше 0.9700\"\n"};
